package com.kitehybrid.platform.order;
import com.kitehybrid.platform.broker.application.auth.KiteAuthenticationSession; import com.kitehybrid.platform.instrument.domain.*; import com.kitehybrid.platform.instrument.infrastructure.InMemoryInstrumentRegistry; import com.kitehybrid.platform.marketdata.application.*; import com.kitehybrid.platform.marketdata.domain.Tick; import com.kitehybrid.platform.marketdata.infrastructure.InMemoryLatestMarketDataStore; import com.kitehybrid.platform.order.application.*; import com.kitehybrid.platform.order.domain.*; import com.kitehybrid.platform.order.domain.command.*; import com.kitehybrid.platform.risk.application.RiskDecisionStore; import com.kitehybrid.platform.risk.domain.*; import com.kitehybrid.platform.shared.domain.*; import com.kitehybrid.platform.shared.domain.Identifiers.*; import io.micrometer.core.instrument.simple.SimpleMeterRegistry; import java.math.BigDecimal; import java.time.*; import java.util.*; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class ExecutionSafetyPolicyTest {
 private static final Instant NOW=Instant.parse("2026-09-26T10:00:00Z"); private final Clock clock=Clock.fixed(NOW,ZoneOffset.UTC); private final Instrument instrument=Instrument.create(new BrokerInstrumentId("ZERODHA","1"),"ABC","NSE","CASH",InstrumentType.CASH,Optional.empty(),Optional.empty(),new BigDecimal("0.05"),1);
 @Test void ordinaryDefaultsDenyAndArmingDoesNotSurviveNewService(){var arm=new RuntimeExecutionArming();assertFalse(arm.armed(NOW));arm.arm(Duration.ofMinutes(1),NOW);assertTrue(arm.armed(NOW));assertFalse(new RuntimeExecutionArming().armed(NOW));}
 @Test void fullySafeSyntheticCaseAllowsExactlyOneAuthorization(){var registry=new InMemoryInstrumentRegistry();registry.replace(List.of(instrument),NOW);var market=new InMemoryLatestMarketDataStore();market.update(new Tick(instrument.id(),new BigDecimal("10"),NOW));var limits=new RiskLimits(true,10,new BigDecimal("1000"),10,new BigDecimal("1000"),Duration.ofMinutes(1),Duration.ofMinutes(1),BigDecimal.ONE,BigDecimal.ONE);var props=new OrderExecutionProperties(true,Set.of(instrument.id()),1,new BigDecimal("20"),Duration.ofMinutes(1),Duration.ofMinutes(1),limits.version(),"phase9");var cmd=new PlaceOrder("safe",instrument.id(),OrderSide.BUY,1,OrderType.MARKET,OrderProduct.DELIVERY,OrderValidity.DAY,Optional.empty(),Optional.empty(),0,OrderVariety.REGULAR);var id=new OrderId(UUID.randomUUID());var order=new OrderRecord(id,cmd,OrderState.RISK_APPROVED,Optional.empty(),Optional.of(BrokerCorrelationId.generate()),Optional.empty(),NOW,NOW,2);var risks=mock(RiskDecisionStore.class);when(risks.find(id)).thenReturn(Optional.of(new RiskDecision(id,1,RiskDecision.Outcome.APPROVED,RiskReason.APPROVED,NOW,limits.version())));var session=mock(KiteAuthenticationSession.class);when(session.enabled()).thenReturn(true);when(session.authenticated()).thenReturn(true);when(session.tokenAvailable()).thenReturn(true);var repo=mock(OrderRepository.class);when(repo.hasDangerousUnresolvedOrders()).thenReturn(false);var health=new MarketDataHealth(MarketDataGateway.State.CONNECTED,MarketDataHealth.Status.FRESH,MarketDataHealth.Reason.NONE,Optional.of(NOW),Optional.of(NOW),Optional.of(NOW),1,1,0,1,1,0,0,0,0);var arm=new RuntimeExecutionArming();arm.arm(Duration.ofMinutes(1),NOW);var policy=new ExecutionSafetyPolicy(props,arm,()->false,session,risks,registry,market,()->health,repo,clock,new SimpleMeterRegistry(),ExecutionAuthorizationAuditStore.NOOP);assertTrue(policy.evaluate(order).allowed());verify(repo).hasDangerousUnresolvedOrders();}
 @Test void eachDenyDecisionIsBounded(){var props=new OrderExecutionProperties(false);var policy=new ExecutionSafetyPolicy(props,new RuntimeExecutionArming(),()->false,mock(KiteAuthenticationSession.class),mock(RiskDecisionStore.class),new InMemoryInstrumentRegistry(),new InMemoryLatestMarketDataStore(),()->null,mock(OrderRepository.class),clock,new SimpleMeterRegistry(),ExecutionAuthorizationAuditStore.NOOP);var cmd=new PlaceOrder("deny",new InstrumentId(UUID.randomUUID()),OrderSide.BUY,1,OrderType.MARKET,OrderProduct.DELIVERY,OrderValidity.DAY,Optional.empty(),Optional.empty(),0,OrderVariety.REGULAR);var id=new OrderId(UUID.randomUUID());var order=new OrderRecord(id,cmd,OrderState.RISK_APPROVED,Optional.empty(),Optional.of(BrokerCorrelationId.generate()),Optional.empty(),NOW,NOW,2);var d=policy.evaluate(order);assertFalse(d.allowed());assertEquals(ExecutionDenialReason.EXECUTION_DISABLED,d.reason());}
}
